import java.io.*;
import java.util.*;

public class Main {
    static byte[] buf;
    static int pos;

    static String next() {
        while (pos < buf.length && buf[pos] <= 32) pos++;
        int start = pos;
        while (pos < buf.length && buf[pos] > 32) pos++;
        return new String(buf, start, pos - start);
    }

    static long nextLong() {
        while (buf[pos] <= 32) pos++;
        boolean neg = buf[pos] == 45;
        if (neg) pos++;
        long r = 0;
        while (pos < buf.length && buf[pos] > 32) r = r * 10 + (buf[pos++] - 48);
        return neg ? -r : r;
    }

    static int nextInt() { return (int) nextLong(); }

    public static void main(String[] args) throws IOException {
        buf = System.in.readAllBytes();
        int n = nextInt(), k = nextInt();
        long[] a = new long[n];
        for (int i = 0; i < n; i++) a[i] = nextLong();
        Arrays.sort(a);
        long low = 0, high = a[n - 1] - a[0];
        while (low < high) {
            long mid = (low + high + 1) / 2, last = a[0];
            int count = 1;
            for (int i = 1; i < n; i++)
                if (a[i] - last >= mid) {
                    count++;
                    last = a[i];
                }
            if (count >= k) low = mid;
            else high = mid - 1;
        }
        System.out.println(low);
    }
}

package main

import (
	"bufio"
	"io"
	"os"
	"strconv"
	"sort"
)

var data []byte
var pos int

func next() []byte {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	start := pos
	for pos < len(data) && data[pos] > ' ' {
		pos++
	}
	return data[start:pos]
}

func nextInt() int64 {
	b := next()
	neg := len(b) > 0 && b[0] == '-'
	if neg {
		b = b[1:]
	}
	var r int64
	for _, c := range b {
		r = r*10 + int64(c-'0')
	}
	if neg {
		return -r
	}
	return r
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	w := bufio.NewWriter(os.Stdout)
	defer w.Flush()
	n, k := int(nextInt()), int(nextInt())
	a := make([]int64, n)
	for i := range a {
		a[i] = nextInt()
	}
	sort.Slice(a, func(i, j int) bool { return a[i] < a[j] })
	low, high := int64(0), a[n-1]-a[0]
	for low < high {
		mid, last, count := (low+high+1)/2, a[0], 1
		for _, v := range a[1:] {
			if v-last >= mid {
				count++
				last = v
			}
		}
		if count >= k {
			low = mid
		} else {
			high = mid - 1
		}
	}
	w.WriteString(strconv.FormatInt(low, 10) + "\n")
}
